const { Pool } = require('pg');
const pool = new Pool();

async function inSerializable(work, maxAttempts = 5) {
  for (let attempt = 1; ; attempt++) {
    const client = await pool.connect();      // вся транзакция на одном соединении
    try {
      await client.query('BEGIN ISOLATION LEVEL SERIALIZABLE');
      const result = await work(client);
      await client.query('COMMIT');           // 40001 может прийти и здесь
      return result;
    } catch (err) {
      await client.query('ROLLBACK').catch(() => {});
      const retryable = err.code === '40001' || err.code === '40P01';
      if (!retryable || attempt === maxAttempts) throw err;
      // пауза с разбросом, чтобы конкуренты не столкнулись снова
      await new Promise(r => setTimeout(r, 2 ** attempt * 10 + Math.random() * 20));
    } finally {
      client.release();
    }
  }
}

