const sent = [];
let attempt = 0;
async function transfer() {                // имитация транзакции на Serializable
  attempt++;
  sent.push(`письмо №${attempt}`);         // побочный эффект внутри: ошибка
  if (attempt < 3) throw Object.assign(new Error('could not serialize'), { code: '40001' });
  return 'COMMIT';
}
async function withRetry(fn, max = 5) {
  for (let i = 1; ; i++) {
    try { return await fn(); }
